export const REPEATABLE_MASTERIES = [
  'Schwerpunkt', 'Jäger', 'Feind', 'Tierkenner', 'Geländekunde',
  'Umgebungssinne', 'Bestienjäger', 'Erzfeind', 'Legendenjäger',
  'Meisterjäger', 'Tierexperte'
];

export const isMasteryRepeatable = (masteryName: string): boolean => {
  if (REPEATABLE_MASTERIES.some(rm => masteryName.includes(rm))) return true;
  if (masteryName.includes('Schwerpunkt') || masteryName.includes('Spezialisierung')) return true;
  return false;
};

