    "baseName": "Großmeister",
    "page": 201,
    "source": "GRW",
    "desc": "Der Abenteurer ist ein vollendeter Großmeister. Bei jedem Wurf in dieser Magieschule darf er einen zusätzlichen W10 werfen. Dieser Würfel wird nicht für die Ermittlung eines Patzers gewertet und kann nur genutzt werden, wenn kein Patzer vorliegt. Entsprechend muss der Würfel klar von den anderen Würfeln unterscheidbar sein (etwa indem er separat geworfen wird oder eine andere Farbe hat). Ein Großmeister hat bei einem Standardwurf also 3 Würfel, von denen die höchsten 2 gewertet werden, bei einem Risikowurf 5 Würfel, von denen die höchsten 2 gewertet werden, und bei einem Sicherheitswurf 3 Würfel, von denen der höchste gewertet wird. Ein Patzer trifft bei Standard- und Risikowurf nur auf, wenn die 2 bzw. 4 normalen Würfel ihn anzeigen. Bei einem Sicherheitswurf ist wie üblich kein Patzer möglich.",
