      "name": "Antäuschen I (S1)",
      "baseName": "Antäuschen I",
      "page": 101,
      "source": "GRW",
      "desc": "Bei einer erfolgreichen Aktiven Abwehr mit der Fertigkeit Akrobatik erhält der Abenteurer 1 zusätzlichen Erfolgsgrad, sofern er ausreichend Platz zur Verfügung hat. Diese Meisterschaft kommt nur zum Tragen, wenn Rüstungen, Schilde, Parierwaffen und sonstige Ausrüstung des Abenteurers eine Gesamt-Behinderung von 1 und einen Tick-Zuschlag von 0 nicht überschreiten. Bei der Berechnung von Gesamt-Behinderung und Tick-Zuschlag werden nur die Werte der Ausrüstung sowie etwaige Verbesserungen durch hohe Gegenstandsqualität betrachtet. Andere Modifikationen, zum Beispiel Verringerungen von Behinderung oder Tick-Zuschlag aus Meisterschaften, Zaubern oder einer Personalisierung, kommen ebenso wenig zum Tragen wie temporäre Erhöhungen, zum Beispiel aus Zuständen.",
