      "baseName": "Ausweichen I",
      "page": 101,
      "source": "GRW",
      "desc": "Die Verteidigung des Abenteurers erhöht sich um 2 Punkte, wenn er weder Rüstungen noch Schilde oder Parierwaffen trägt, er sich des Angriffs bewusst ist und ihm ausreichend Platz zur Verfügung steht. Dieser Bonus reduziert sich, je nachdem, wie stark der Abenteurer belastet ist. Trägt er Ausrüstung mit einer Gesamt-Behinderung von maximal 1 und einem Tick-Zuschlag von 0, reduziert sich der Bonus auf 1 Punkt. Belastet ihn seine Ausrüstung noch stärker, kommt diese Meisterschaft nicht zum Tragen. Bei der Berechnung von Gesamt-Behinderung und Tick-Zuschlag werden nur die Werte der Ausrüstung sowie etwaige Verbesserungen durch hohe Gegenstandsqualität betrachtet. Andere Modifikationen, zum Beispiel Verringerungen von Behinderung oder Tick-Zuschlag aus Meisterschaften, Zaubern oder einer Personalisierung, kommen ebenso wenig zum Tragen wie temporäre Erhöhungen, zum Beispiel aus Zuständen.",
