      "baseName": "Ausweichen III",
      "page": 102,
      "source": "GRW",
      "desc": "Die Verteidigung des Abenteurers erhöht sich um 6 Punkte, wenn er sich des Angriffs bewusst ist und ihm ausreichend Platz zur Verfügung steht. Trägt der Abenteurer irgendwelche Rüstungen, Schilde oder Parierwaffen, kommt diese Meisterschaft nicht zum Tragen. Dasselbe gilt für sonstige Ausrüstung mit Einfluss auf Behinderung oder Tick-Zuschlag. Voraussetzung: Meisterschaft Ausweichen II",
