      "baseName": "Hammerschlag",
      "page": 97,
      "source": "GRW",
      "desc": "[Manöver] Bei einem erfolgreichen Nahkampfangriff mit diesem Manöver verursacht der Abenteurer 1W6 Schaden mehr.",
