      "source": "GRW",
      "desc": "Kampfhandlungen unter Wasser sind normalerweise um 6 erschwert. Ein Abenteurer mit dieser Meisterschaft ist so geübt darin, dass er die Erschwernis für Kampfhandlungen halbiert. Beim Kampf in hüfthohem Wasser kann er den Malus komplett ignorieren. Voraussetzung: Meisterschaft Arbeit unter Wasser",
