      "baseName": "Arkane Verteidigung II",
      "page": 106,
      "source": "GRW",
      "desc": "Der Abenteurer kann sich besser gegen Magie verteidigen. Wenn er einen Zauber, der gegen ihn gewirkt wird, erfolgreich identifiziert, erhält er einen Bonus in Höhe von 6 Punkten auf eine eventuelle Aktive Abwehr. Voraussetzung: Meisterschaft Arkane Verteidigung I",
