  "Klingenwaffen": [
    {
      "name": "Ausfall (S1)",
      "baseName": "Ausfall",
      "page": 98,
      "source": "GRW",
      "desc": "[Manöver] Der Gegner erleidet bei diesem Manöver den üblichen Schaden und verliert zusätzlich 3 Ticks. Sollte das Manöver gelingen, kann der Gegner nicht mehr von einem anderen Ausfall betroffen werden, bevor er das nächste Mal gehandelt hat.",
      "tier": 1,
      "minSkillValue": 6,
      "skill": "Klingenwaffen",
      "manoever": true,
      "prerequisiteText": null,
      "prerequisite": null,
      "prerequisiteStatus": null,
      "id": "sm:617824fa-09fc-5c22-9350-0eef9d1bf273"
    },
    {
      "name": "Verteidigungswirbel (S1)",
      "baseName": "Verteidigungswirbel",
      "page": 98,
      "source": "GRW",
      "desc": "[Manöver] Zusätzlich zu seinem regulären Nahkampfangriff bringt der Kämpfer sich mit diesem Manöver in eine vorteilhafte defensive Position. Für den nächsten Angriff gegen seine Verteidigung in diesem Kampf ist diese um 2 Punkte erhöht. Zudem kann er weitere Erfolgsgrade nutzen, um seine Verteidigung pro eingesetztem Erfolgsgrad um einen weiteren Punkt zu erhöhen.",
      "tier": 1,
      "minSkillValue": 6,
      "skill": "Klingenwaffen",
      "manoever": true,
      "prerequisiteText": null,
      "prerequisite": null,
      "prerequisiteStatus": null,
      "id": "sm:202d48fb-0b90-53d1-b75e-b05c55b26815"
    },
    {
      "name": "Verwirrung (S1)",
      "baseName": "Verwirrung",
      "page": 98,
      "source": "GRW",
      "desc": "[Manöver] Dieser Nahkampfangriff geht gegen den Geistigen Widerstand und richtet bei Erfolg nur halben Schaden an. Dafür erhält der nächste Angriff gegen denselben Gegner (egal von wem) einen Bonus in Höhe von 2 Punkten. Der Angreifer kann weitere Erfolgsgrade einsetzen, um diesen Bonus um 1 je Erfolgsgrad zu erhöhen. Ein Kämpfer kann nur Ziel einer Verwirrung zur gleichen Zeit sein.",
      "tier": 1,
      "minSkillValue": 6,
      "skill": "Klingenwaffen",
      "manoever": true,
      "prerequisiteText": null,
      "prerequisite": null,
      "prerequisiteStatus": null,
      "id": "sm:c84f1c88-d5a4-5877-886a-d27220bcda69"
    },
    {
      "name": "Gezielte Treffer (S2)",
      "baseName": "Gezielte Treffer",
      "page": 98,
      "source": "GRW",
      "desc": "Die präzisen Nahkampfangriffe des Abenteurers erlauben es ihm, bis zu 2 Punkte Schadensreduktion bei seinen Gegnern zu ignorieren, sofern er mit einer Klingenwaffe kämpft. Dies zählt zusätzlich zu allen anderen Möglichkeiten des Kämpfers, die Schadensreduktion seines Gegners zu umgehen.",
      "tier": 2,
      "minSkillValue": 9,
      "skill": "Klingenwaffen",
      "manoever": false,
      "prerequisiteText": null,
      "prerequisite": null,
      "prerequisiteStatus": null,
      "id": "sm:106adc26-f842-5936-ba2b-666f7002abdb"
    },
    {
      "name": "Klingenwirbel (S2)",
      "baseName": "Klingenwirbel",
      "page": 98,
      "source": "GRW",
      "desc": "[Manöver] Gelingt das Manöver Klingenwirbel, rückt der Angreifer nach Abhandlung des Nahkampfangriffs noch einmal seine halbe Waffengeschwindigkeit in Ticks vor. Dafür kann er einen zweiten sofortigen Nahkampfangriff mit derselben Waffe und einem Malus in Höhe von 3 Punkten ausführen. Hierfür muss er nicht die sonst übliche Waffengeschwindigkeit aufwenden. Dieser Angriff kann gegen ein zweites in Nahkampfdistanz befindliches Ziel gerichtet sein, darf aber keine Meisterschafts-Manöver verwenden.",
      "tier": 2,
      "minSkillValue": 9,
      "skill": "Klingenwaffen",
      "manoever": true,
      "prerequisiteText": null,
      "prerequisite": null,
      "prerequisiteStatus": null,
      "id": "sm:7edb4c77-e27f-5bd0-bdca-c1258bf75830"
    },
    {
      "name": "Riposte (S2)",
      "baseName": "Riposte",
      "page": 98,
      "source": "GRW",
      "desc": "Diese Meisterschaft kann nur bei einer Aktiven Abwehr durch Klingenwaffen zur Erhöhung der Verteidigung gegen einen gegnerischen Nahkampfangriff eingesetzt werden. Dies muss vorher angesagt werden, die Aktive Abwehr erhält einen Malus in Höhe von 3 Punkten. Wird der gegnerische Nahkampfangriff vollständig abgewehrt, erhält der Kämpfer einen Bonus in Höhe von 1 Punkt bei seinem nächsten Nahkampfangriff mit Klingenwaffen, solange dieser gegen den Angreifer gerichtet ist. Dieser Bonus erhöht sich um jeweils 1 Punkt für jeden negativen Erfolgsgrad des Angreifers.",
      "tier": 2,
      "minSkillValue": 9,
      "skill": "Klingenwaffen",
      "manoever": false,
      "prerequisiteText": null,
      "prerequisite": null,
      "prerequisiteStatus": null,
      "id": "sm:71488112-dd39-5f51-b603-5cc04af00c3d"
    },
    {
      "name": "Blutiger Aderlass (S3)",
      "baseName": "Blutiger Aderlass",
      "page": 99,
      "source": "GRW",
      "desc": "[Manöver] Dieser Nahkampfangriff verursacht zusätzlich zum normalen Schaden beim Gegner den Zustand Blutend 1. Voraussetzung: Meisterschaft Gezielte Treffer in der Fertigkeit Klingenwaffen",
      "tier": 3,
      "minSkillValue": 12,
      "skill": "Klingenwaffen",
      "manoever": true,
      "prerequisiteText": "Meisterschaft Gezielte Treffer in der Fertigkeit Klingenwaffen",
      "prerequisite": {
        "typ": "besitzt_regel",
        "ziel_id": "sm:106adc26-f842-5936-ba2b-666f7002abdb",
        "ziel_revision": "4360dde87a12238c0f0456a9302dd3c6e8de5027fe23b64a98f589e5195169f8",
        "ziel_pdf_sha256": "f824ffc4850360d07e1633bdc27cc922dd2ae498320187e7e9e3def3a5dd6cc3",
        "ziel_werk_id": null,
        "ziel_ausgabe": null,
        "ziel_kategorie": "meisterschaften",
        "ziel_name": "Gezielte Treffer"
      },
      "prerequisiteStatus": "eindeutig_zugeordnet",
      "id": "sm:0d0616cb-43cf-5130-883b-4b7d7a548d8f"
    },
    {
      "name": "Eleganter Klingenwirbel (S3)",
      "baseName": "Eleganter Klingenwirbel",
      "page": 99,
      "source": "GRW",
      "desc": "Der zweite Angriff des Manövers Klingenwirbels ist bei Verwendung einer Klingenwaffe für Kenner dieser Meisterschaft nicht mehr erschwert. Zudem kann man beim zweiten Angriff eines Klingenwirbels auch Meisterschafts-Manöver einsetzen (nicht aber einen weiteren Klingenwirbel). Voraussetzung: Meisterschaft Klingenwirbel in der Fertigkeit Klingenwaffen",
      "tier": 3,
      "minSkillValue": 12,
      "skill": "Klingenwaffen",
      "manoever": false,
      "prerequisiteText": "Meisterschaft Klingenwirbel in der Fertigkeit Klingenwaffen",
      "prerequisite": {
        "typ": "besitzt_regel",
        "ziel_id": "sm:7edb4c77-e27f-5bd0-bdca-c1258bf75830",
        "ziel_revision": "072d6035e745b596895093cb536cff9fe8ced3cf0f3f21347afe505979c80a09",
        "ziel_pdf_sha256": "f824ffc4850360d07e1633bdc27cc922dd2ae498320187e7e9e3def3a5dd6cc3",
        "ziel_werk_id": null,
        "ziel_ausgabe": null,
        "ziel_kategorie": "meisterschaften",
        "ziel_name": "Klingenwirbel"
      },
      "prerequisiteStatus": "eindeutig_zugeordnet",
      "id": "sm:16732244-cf1a-5eb4-a380-84f8def5ea73"
    }
  ],
