      "source": "GRW",
      "desc": "Der Zauberer kann anhaltende Zaubereffekte mit geringer Mühe bannen. Seine erschöpften Fokuspunkten für das Wirken von Bannzaubern des Typus Zauber brechen sind um 2 Punkte verringert (Minimum 1).",
