      "baseName": "Kontrolle der Form",
      "page": 217,
      "source": "GRW",
      "desc": "Der Zauberer erhält einen Bonus in Höhe von 2 Punkten auf Verwandlungszauber, die gegen den Körperlichen Widerstand oder die Verteidigung gerichtet sind.",
