      "source": "GRW",
      "desc": "Wird versucht, eine vom Zauberer durchgeführte Verwandlung zu identifizieren, erleidet der Versuch einen Malus in Höhe von 3 Punkten. Voraussetzung: Meisterschaft Bannung der Form",
