            "ziel_revision": "eb93f10d8fb60ca500ee2085c111e8cdde97ad81942187648c48f5739fce2219",
            "ziel_pdf_sha256": "f824ffc4850360d07e1633bdc27cc922dd2ae498320187e7e9e3def3a5dd6cc3",
            "ziel_werk_id": null,
