      "source": "GRW",
      "desc": "Der Abenteurer wählt eine konkrete Art von Sagenkreatur aus (Wesen des Typus Geisterwesen, Monster, Untoter oder Feenwesen). Gegen diese erhält er einen Bonus in Höhe von 3 Punkten auf Angriffe und Proben auf Wahrnehmung und Überleben. Diese Meisterschaft kann mehrfach gewählt werden. Jedes Mal muss eine neue Art gewählt werden. Voraussetzung: Schwerpunkt Legendäre Kreaturen",
