      "source": "GRW",
      "desc": "Der Abenteurer kann Zustände wie Angsterfüllt, Rasend oder Panisch beheben. Dies dauert eine Minute. Die Schwierigkeit liegt je nach Trauma zwischen 20 und 25. Mit Ausgabe eines Splitterpunktes können magische Furcht und ähnliches behoben werden, wenn dem Abenteurer eine vergleichende Probe gegen das Ergebnis der Zauberprobe gelingt.",
