      "baseName": "Herr über den Geist",
      "page": 113,
      "source": "GRW",
      "desc": "Alle Proben des Abenteurers auf Zauber der Typen Mental, Gedanken oder Moral erhalten einen Bonus in Höhe von 2 Punkten. Voraussetzung: Meisterschaft Beruhigen",
