      "source": "GRW",
      "desc": "Der Abenteurer wählt einen der folgenden Typen aus: Bärenartiger, Fisch, Großwild, Hundeartiger, Insekt, Katzenartiger, Kleinwild, Reptil, Spinnentier, Vogel. Gegen Wesen, die den Typus Tier und diesen Typus aufweisen, erhält er einen Bonus in Höhe von 3 Punkten auf Angriffe. Diese Meisterschaft kann mehrfach gewählt werden. Jedes Mal muss ein neuer Typus gewählt werden.",
