      "baseName": "Tierexperte",
      "page": 122,
      "source": "GRW",
      "desc": "Der Abenteurer wählt einen Typus, für den er die Meisterschaft Tierkenner besitzt. Der Bonus erhöht sich auf 5. Tierexperte kann unter den Bedingungen wie Tierkenner mehrfach gewählt werden. Voraussetzung: Meisterschaft Tierkenner",
