      "page": 122,
      "source": "GRW",
      "desc": "Der Abenteurer wählt eine Tierart, für die er die Meisterschaft Tierexperte besitzt. Alle Fernkampfangriffe, bei denen er mindestens 2 Ticks zielen kann, richten gegen diese Tierart 5 Punkte zusätzlichen Schaden an. Voraussetzung: Meisterschaft Tierexperte",
