      "desc": "Der Jäger kann ein Tier perfekt verwerten. Er erhält von einem Tier 50 % mehr Nahrung und Beute (ausgenommen Einzelstücke wie das Horn eines Einhorns). Voraussetzung: Meisterschaft Waidmann",
