      "desc": "Der Abenteurer kann bis zu 3 Punkte Malus, die durch äußere Umstände wie Wetter, Sicht oder andere Störungen zustande kommen, bei seinen Fertigkeitsproben ignorieren. Voraussetzung: Meisterschaft Kühler Kopf I",
