      "desc": "Bevor der Abenteurer einen Risikowurf für einen Nahkampfangriff mit einer Hiebwaffe benutzt, kann er sich entscheiden, bis zu seiner nächsten Aktion einen Malus in Höhe von 4 Punkten auf die Verteidigung hinzunehmen, um einen Bonus in Höhe seiner halben Stärke zum Schaden zu addieren.",
