      "source": "GRW",
      "desc": "Packt ein Kämpfer mit dieser Meisterschaft seinen Gegner im Handgemenge mit dem Manöver Umklammern, wird zusätzlich zum Zustand Ringend dessen Verteidigung um 2 weitere Punkte gesenkt. Auch erhalten die Aktionen des Gegners einen zusätzlichen Malus in Höhe von 2 Punkten. Voraussetzung: Meisterschaft Umklammern in der Fertigkeit Handgemenge",
