      "source": "GRW",
      "desc": "Der Kämpfer hat gelernt, wie er seinen Gegner noch stärker verletzen kann, während er ihn von den Beinen holt. Ein über Handgemenge ausgeführter Nahkampfangriff mit dem Manöver Umreißen verursacht den vollen Schaden statt wie üblich den halben Schaden. Voraussetzung: Meisterschaft Umreißen in der Fertigkeit Handgemenge",
