        "ziel_id": "sm:a1d24fcc-8f5e-512f-bdbf-a4f298837d63",
        "ziel_revision": "aa984d32e8607c17a7afb00cd208f18078c22e183b180a58501dff01fed26289",
        "ziel_pdf_sha256": "f824ffc4850360d07e1633bdc27cc922dd2ae498320187e7e9e3def3a5dd6cc3",
        "ziel_werk_id": null,
        "ziel_ausgabe": null,
