      "baseName": "Schlachtplan (Verteidigung)",
      "page": 104,
      "source": "GRW",
      "desc": "Der Abenteurer bündelt mit einer kontinuierlichen Aktion (10 Ticks) die Verteidigungskraft seiner Gefährten. Er muss eine Probe auf Anführen gegen 20 ablegen. Alle Verbündeten, die ihn hören (maximal seine doppelte Ausstrahlung), erhalten einen Bonus in Höhe von 1 Punkt (+1 pro Erfolgsgrad) auf ihre Verteidigung. Alle 10 Ticks sinkt der Bonus um 1. Entwirft der Abenteurer einen neuen Schlachtplan, entfällt jeder Bonus des alten. Voraussetzung: Meisterschaft Sammeln",
      "tier": 2,
      "minSkillValue": 9,
