      "page": 124,
      "source": "GRW",
      "desc": "Der Sammler ist besonders effizient. Seine Proben zum Suchen von Kräutern, Nahrung oder Zutaten benötigen nur 1 Stunde (statt 3). Voraussetzung: Schwerpunkt Kräutersuche/Zutaten sammeln oder Nahrungssuche",
