            "ziel_id": "sm:749f3908-0c8f-510b-8d0d-47d55d81fdf3",
            "ziel_revision": "b7abdbe6e673d82266c87cd554cd26ce0ae9a965c1781e279ae34b41489f850c",
            "ziel_pdf_sha256": "f824ffc4850360d07e1633bdc27cc922dd2ae498320187e7e9e3def3a5dd6cc3",
            "ziel_werk_id": null,
