      "baseName": "Dringliche Botschaft",
      "page": 205,
      "source": "GRW",
      "desc": "Der Zauberer kann Erkenntniszauber des Typus Botschaft auch dann noch wirken, wenn er keine Fokuspunkte mehr zur Verfügung hat. Hierfür muss er Lebensenergie in Höhe der Fokuskosten aufwenden.",
