        "ziel_id": "sm:6c1d0007-ba2b-5512-a97a-9918f3a717ad",
        "ziel_revision": "d5748127d584e82989ff491c6b3c4376d4400e2642fd2a5ff40b88b7976ba551",
        "ziel_pdf_sha256": "f824ffc4850360d07e1633bdc27cc922dd2ae498320187e7e9e3def3a5dd6cc3",
        "ziel_werk_id": null,
