      "desc": "Der Zauberer hat gelernt, die Sprache seines Tiervertrauten zu verstehen. Er kann mit ihm kommunizieren, wobei die Art der Kommunikation durch den Verstand des Vertrauten begrenzt ist. Voraussetzung: Meisterschaft Vertrautenband",
