      "source": "GRW",
      "desc": "Die Stimme des Zauberers trägt auf Wunsch und durch Einsatz von 2 erschöpften Fokuspunkten für 5 Minuten besonders weit und erklingt besonders laut. Auf diese Art kann er beispielsweise weit entfernten Gefährten etwas zurufen oder eine donnernde Ansprache halten.",
