/**
 * MASTERIES_DB with transparent alias resolution (supporting both 'Schlösser & Fallen' and 'Schlösser und Fallen',
 * as well as 'Geschichte & Mythen' and 'Geschichte und Mythen') while preserving original keys/values for counting.
 */
export const MASTERIES_DB: Record<string, MasteryEntry[]> = new Proxy(RAW_MASTERIES_DB, {
  get(target, prop, receiver) {
    if (typeof prop === 'string') {
      if (prop in target) return target[prop];
      const alt1 = prop.replace(/\s+und\s+/g, ' & ');
      if (alt1 in target) return target[alt1];
      const alt2 = prop.replace(/\s+&\s+/g, ' und ');
      if (alt2 in target) return target[alt2];
    }
    return Reflect.get(target, prop, receiver);
  },
  has(target, prop) {
    if (typeof prop === 'string') {
      if (prop in target) return true;
      const alt1 = prop.replace(/\s+und\s+/g, ' & ');
      if (alt1 in target) return true;
      const alt2 = prop.replace(/\s+&\s+/g, ' und ');
      if (alt2 in target) return true;
    }
    return Reflect.has(target, prop);
  },
});

